mapper.sql:
WHERE a.achievement_type = 'LECTURE_IMPROVEMENT'
  AND a.deleted_yn = 'N'

    AND a.management_item_code = #{criteria.managementItemCode}


    AND a.achievement_status = #{criteria.achievementStatus}


    AND (FALSE

        OR a.teacher_user_id = #{userId}


        OR EXISTS (
            SELECT 1
            FROM organization_user_mappings r
            JOIN organization_user_mappings t ON t.organization_code = r.organization_code
            WHERE r.user_id = #{userId}
              AND r.status = 'ACTIVE'
              AND t.user_id = a.teacher_user_id
              AND t.status = 'ACTIVE'
        )


        OR EXISTS (
            SELECT 1
            FROM evaluation_organization_mappings p
            JOIN organization_user_mappings t ON t.organization_code = p.organization_code
            WHERE p.user_id = #{userId}
              AND p.business_type = 'FACULTY_ACHIEVEMENT'
              AND p.data_scope IN ('DEPARTMENT', 'COLLEGE', 'BUSINESS', 'ALL')
              AND t.user_id = a.teacher_user_id
              AND t.status = 'ACTIVE'
        )

    )

mapper.select:
SELECT 


ORDER BY a.achievement_date DESC, a.achievement_id DESC
LIMIT #{criteria.pageSize}
OFFSET #{criteria.offset}

SELECT COUNT(*)
FROM evaluation_element_management_item_settings s
WHERE s.management_item_code = #{code}
  AND s.evaluation_year = #{year}
  AND s.area_code = 'EDUCATION'
  AND s.target_scope = #{organization}
  AND s.active_yn = 'Y'
  AND s.teacher_editable_yn = 'Y'
  AND s.evaluation_confirmed_yn = 'N'
  AND CURRENT_DATE BETWEEN s.effective_start_date AND s.effective_end_date

mapper.insert:
INSERT INTO education_achievements (
    achievement_type, teacher_user_id, organization_code, evaluation_year,
    management_item_code, achievement_date, attachment_ids, created_by, updated_by, request_id
)
VALUES (
    'LECTURE_IMPROVEMENT', #{teacherUserId}, #{organizationCode}, #{evaluationYear},
    #{managementItemCode}, #{achievementDate}, CAST(#{attachmentIds} AS jsonb),
    #{userId}, #{userId}, #{requestId}
)

INSERT INTO lecture_improvement_achievement_details (
    achievement_id, performance_content, academic_year, semester_code
)
VALUES (
    #{id}, #{body.achievementContent}, #{body.academicYear}, CAST(#{body.semester} AS varchar)
)

INSERT INTO data_change_histories (
    target_business, target_key, change_type, field_name,
    before_value, after_value, changed_by, change_reason, request_id
)
VALUES (
    'education_achievements', CAST(#{id} AS varchar), #{action}, #{field},
    #{before}, #{after}, #{userId}, '강의개선 실적 저장', #{requestId}
)
